RUNS=[('11M',S11),('15M',S15),('22M',S22),('33M',S33),('47M',S47),('88M',MAIN88)]
W,H=780,500; L,R,T,B=70,24,24,62
X0,X1=3e14,1.5e18; Y0,Y1=3.2,6.6
def sx(c): return L+(math.log10(c)-math.log10(X0))/(math.log10(X1)-math.log10(X0))*(W-L-R)
def sy(y): return H-B-(y-Y0)/(Y1-Y0)*(H-T-B)
def svg(th,cols):
    ink,mut,grid,surf=th
    o=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    o.append(f'<defs><clipPath id="c"><rect x="{L}" y="{T}" width="{W-L-R}" height="{H-T-B}"/></clipPath></defs>')
    for e in range(15,19):
        x=sx(10**e)
        o.append(f'<line x1="{x:.1f}" x2="{x:.1f}" y1="{T}" y2="{H-B}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{x:.1f}" y="{H-B+20}" fill="{mut}" font-size="13" text-anchor="middle">10^{e}</text>'.replace('10^'+str(e),'10'+''.join('⁰¹²³⁴⁵⁶⁷⁸⁹'[int(d)] for d in str(e))))
    for y in (3.5,4.0,4.5,5.0,5.5,6.0,6.5):
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(y):.1f}" y2="{sy(y):.1f}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<text x="{L-8}" y="{sy(y)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{y:.1f}</text>')
    o.append(f'<text x="{(L+W-R)/2}" y="{H-16}" fill="{ink}" font-size="14" text-anchor="middle">Training compute, 6 × parameters × tokens (FLOPs, log scale)</text>')
    o.append(f'<text transform="translate(20,{(T+H-B)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Validation loss (nats per token)</text>')
    ends=[]
    for (lab,(N,pts)),c in zip(RUNS,cols):
        P=[(6*N*t*1e6,v) for t,v in pts]
        o.append(f'<polyline clip-path="url(#c)" points="{" ".join(f"{sx(x):.1f},{sy(v):.1f}" for x,v in P)}" fill="none" stroke="{c}" stroke-width="2.2"/>')
        x,v=P[-1]; ends.append((lab,x,v,c))
        o.append(f'<circle cx="{sx(x):.1f}" cy="{sy(v):.1f}" r="5" fill="{c}" stroke="{surf}" stroke-width="2"/>')
    for lab,x,v,c in ends:
        dx,dy=(-10,21) if lab=="88M" else (-10,17)
        o.append(f'<text x="{min(sx(x)+dx,W-R):.1f}" y="{sy(v)+dy:.1f}" fill="{ink}" font-size="13" font-weight="bold" text-anchor="end">{lab}: {v:.2f}</text>')
    lx=W-R-250; ly=T+16
    o.append(f'<text x="{lx}" y="{ly}" fill="{ink}" font-size="13">Each curve: one model size, 20 tokens</text>')
    o.append(f'<text x="{lx}" y="{ly+18}" fill="{ink}" font-size="13">per parameter, its own schedule. Dot: end</text>')
    o.append(f'<text x="{lx}" y="{ly+36}" fill="{ink}" font-size="13">of the run. 88M: Part 7.</text>')
    o.append('</svg>'); return '\n'.join(o)
light=('#0b1a33','#4a5b78','#dde5f2','#ffffff'); dark=('#e8eefc','#9fb0cf','#22355a','#0b162d')
LC=('#8db8ee','#5b97e3','#2f78d6','#1a5bb3','#0f3d80','#eb6834'); DC=('#3b6e9e','#4f8fc8','#62acea','#8ccaf5','#c4e6fd','#d95926')
open(sys.argv[1]+'.svg','w').write(svg(light,LC)); open(sys.argv[1]+'-dark.svg','w').write(svg(dark,DC))
